#!/usr/bin/env bash
#
# Check the HTML syntax of the generated pages
#
# Uses html-validate (install it with `make install-test`)
# See https://html-validate.org/ and the rules at https://html-validate.org/rules/

project_dir="$(readlink -f "$1")"

cd "$(dirname "$0")" || exit 1
config_file="$(readlink -f ../resources/.htmlvalidate.json)"

# Folders of vendored third-party libraries, not generated by the blog
ignored_dirs=("libs")

cd "${project_dir}" || exit 1

find_excludes=()
for dir in "${ignored_dirs[@]}"; do
  find_excludes+=(-not -path "*/${dir}/*")
done

files=()
while IFS= read -r -d '' file; do
  files+=("${file}")
done < <(find . -name '*.html' "${find_excludes[@]}" -print0 | sort -z)

echo
for dir in "${ignored_dirs[@]}"; do
  echo "  ignored folder: */${dir}/"
done
for file in "${files[@]}"; do
  echo "  checked: ${file#./}"
done

npx --no-install html-validate --config "${config_file}" "${files[@]}"
